function resolve_latest_message_id(): number | null {
  if (typeof getChatMessages !== 'function') {
    return null;
  }
  const latest = getChatMessages(-1)[0];
  return typeof latest?.message_id === 'number' ? latest.message_id : null;
}

const ZERO_ACTION = { 探索: 0, 狩猎: 0, 采集: 0, 工作: 0, 带队: 0, 大成功: 0, 失败: 0 };

type NpcDraft = {
  种族: string;
  职务: string;
  档位: Schema['具名NPC'][string]['档位'];
   好感度: number;
  饱食度: number;
  体力: number;
  心情: Schema['具名NPC'][string]['心情'];
  状态: string;
  当前位置: string;
  当前任务: string;
  当前想法: string;
  对视时: Schema['具名NPC'][string]['对视时'];
};

function build_core_npc(name: keyof typeof CORE_NPC_SKILLS, draft: NpcDraft): Schema['具名NPC'][string] {
  return {
    种族: CORE_WRECK_NPC_RACE[name] ?? draft.种族,
    职务: draft.职务,
    档位: draft.档位,
    行动履历: { ...ZERO_ACTION },
    孕期: '未孕',
    受孕日: 0,
    好感度: draft.好感度,
    体力: draft.体力,
    心情: draft.心情,
    状态: draft.状态,
    当前位置: draft.当前位置,
    当前任务: draft.当前任务,
    当前想法: draft.当前想法,
    饱食度: draft.饱食度,
    种族系: name === '霜华' ? '食草' : name === '朔春' ? '食肉' : name === '林果' ? '杂食' : '食肉',
    互动状态: '无',
    对视时: draft.对视时,
    注视心声: draft.对视时.心里话 ?? '',
    技能: { ...CORE_NPC_SKILLS[name] },
  };
}

