export type CustomCompanionSkills = {
  狩猎: number;
  战斗: number;
  采集: number;
  后勤: number;
};

export type CustomCompanionNpc = {
  id: string;
  avatar: string;
  name: string;
  gender: string;
  /** 种族名，如「羊角娘」「黑狼娘」→ 写入 MVU 的 种族 字段 */
  种族: string;
  /** 食性 → 写入 MVU 的 种族系 字段；决定口粮与技能适配 */
  食性: '食草系' | '食肉系' | '杂食系';
  appearance: string;
  personality: string;
  background: string;
  skills: CustomCompanionSkills;
  好感度: number;
  饱食度: number;
  体力: number;
  user_relation: string;
};

export function create_empty_companion(): CustomCompanionNpc {
  return {
    id: `npc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    avatar: '',
    name: '',
    gender: '',
    种族: '',
    食性: '杂食系',
    appearance: '',
    personality: '',
    background: '',
    skills: { 狩猎: 0, 战斗: 0, 采集: 0, 后勤: 0 },
    好感度: 50,
    饱食度: 40,
    体力: 80,
    user_relation: '',
  };
}

export function clamp_skill(value: number): number {
  return _.clamp(Math.round(Number(value) || 0), 0, 100);
}

export function clamp_stat(value: number, min: number, max: number): number {
  return _.clamp(Math.round(Number(value) || 0), min, max);
}
