import type { Schema } from '../../../schema';
import { is_storage_building } from './settlementSync';

export type EraProgressItem = { key: string; name: string };
export type EraProgressCategory = { title: string; items: EraProgressItem[] };

/** 时代一通关条件文案，与演进表判定项一致（供 ERA_INFO、[殖民]时代I 等引用） */
export const ERA_ONE_CLEARANCE_SUMMARY =
  '完成演进表全部十项：温饱度≥60、食物储备充足、向心力>80、人口>20、建成防御类建筑≥2座、建成储存类建筑≥2座、建成石砌防风火塘、解锁自主生火、烧制实用陶器、解锁材料分级认知';

const ERA_ONE_PROGRESS: EraProgressCategory[] = [
  {
    title: '生存与人口维度',
    items: [
      { key: '温饱保障', name: '温饱度达60（可持续保障）' },
      { key: '食物储备', name: '拥有过冬/过夏储备' },
      { key: '向心力达标', name: '营地向心力超80' },
      { key: '人口规模', name: '人口规模超20人' },
    ],
  },
  {
    title: '基础设施维度',
    items: [
      { key: '防御体系', name: '建成防御类建筑≥2座' },
      { key: '仓储体系', name: '建成储存类建筑≥2座' },
      { key: '核心火源', name: '建成石砌防风火塘' },
    ],
  },
  {
    title: '核心科技突破',
    items: [
      { key: '自主生火', name: '研发自主生火工具' },
      { key: '制陶技术', name: '烧制出实用陶器' },
      { key: '材料认知跨越', name: '解锁金属与黏土加工' },
    ],
  },
];

const ERA_PROGRESS_TITLES: Record<Schema['世界']['当前时代'], string> = {
  一: '时代一：原始求生 演进表',
  二: '时代二：聚落成型 演进表',
  三: '时代三：文明曙光 演进表',
};

function isBuildingBuilt(data: Schema, name: string): boolean {
  const building = data.营地.当前建筑[name];
  if (!building) {
    return false;
  }
  return building.建筑阶段 === '已建成' || building.建筑阶段 === '受损';
}

function hasInventoryMatch(data: Schema, pattern: RegExp): boolean {
  return Object.entries(data.营地.物品栏).some(
    ([name, item]) => pattern.test(name) && (item?.数量 ?? 0) > 0,
  );
}

function hasBuildingMatch(data: Schema, pattern: RegExp): boolean {
  return Object.keys(data.营地.当前建筑).some(
    name => pattern.test(name) && isBuildingBuilt(data, name),
  );
}

/** 统计「已建成的某类功能建筑」数量（功能标签优先，名称关键词兜底） */
function countBuiltByTag(data: Schema, tag: string, namePattern: RegExp): number {
  return Object.entries(data.营地.当前建筑).filter(([name, b]) => {
    if (!isBuildingBuilt(data, name)) return false;
    const tags = (b as { 功能标签?: string[] }).功能标签;
    if (Array.isArray(tags) && tags.includes(tag)) return true;
    if (tag === '储存') return is_storage_building(name, b as { 功能标签?: string[]; 建筑阶段?: string });
    return namePattern.test(name);
  }).length;
}

export function evaluateEraProgress(data: Schema): Record<string, boolean> {
  const { 营地: camp, 已解锁科技: unlocked } = data;

  return {
    温饱保障: camp.生存指标.温饱度 >= 60,
    食物储备: camp.营地状态.食物储备 === '储备充足',
    向心力达标: camp.向心力 >= 80,
    人口规模: camp.人口 >= 20,
    // 独立围栏与升级仓库已删除，改用「已建成的功能建筑」判定
    防御体系: countBuiltByTag(data, '防御', /护栏|栅栏|围墙/) >= 2,
    仓储体系: countBuiltByTag(data, '储存', /堆架|物资棚|沙土窖|储水陶缸|仓/) >= 2,
    核心火源: isBuildingBuilt(data, '石砌防风火塘'),
    自主生火: unlocked.includes('火源与热加工') || isBuildingBuilt(data, '钻木取火套装'),
    制陶技术: hasInventoryMatch(data, /陶/) || hasBuildingMatch(data, /陶/),
    材料认知跨越: unlocked.includes('材料分级认知'),
  };
}

export function isEraOneClearanceMet(data: Schema): boolean {
  const progress = evaluateEraProgress(data);
  return ERA_ONE_PROGRESS.every(category => category.items.every(item => progress[item.key]));
}

export type EraChecklistRow = {
  key: string;
  name: string;
  /** 当前值（数字项才有）；布尔项省略 */
  current?: number;
  /** 门槛文案，例如「≥60」「≥2座」 */
  threshold?: string;
  met: boolean;
  category: string;
};

/**
 * 时代一通关条件清单（含现值）。
 *
 * 为什么需要它：ERA_ONE_CLEARANCE_SUMMARY 是一段拼接文案，页面无法逐项核对；
 * evaluateEraProgress 只有布尔值，玩家看不到「差多少」。这里把两项合起来，
 * 由前端算好现值与门槛（铁律：AI 不做计数），页面只负责渲染。
 */
export function getEraOneChecklist(data: Schema): EraChecklistRow[] {
  const { 营地: camp, 已解锁科技: unlocked } = data;
  const defense = countBuiltByTag(data, '防御', /护栏|栅栏|围墙/);
  const storage = countBuiltByTag(data, '储存', /堆架|物资棚|沙土窖|储水陶缸|仓/);

  return [
    {
      key: '温饱保障',
      name: '温饱度',
      current: Math.round(Number(camp.生存指标.温饱度 ?? 0)),
      threshold: '≥60',
      met: camp.生存指标.温饱度 >= 60,
      category: '生存与人口',
    },
    {
      key: '食物储备',
      name: '过冬/过夏储备',
      threshold: '储备充足',
      met: camp.营地状态.食物储备 === '储备充足',
      category: '生存与人口',
    },
    {
      key: '向心力达标',
      name: '营地向心力',
      current: Math.round(Number(camp.向心力 ?? 0)),
      threshold: '>80',
      met: camp.向心力 >= 80,
      category: '生存与人口',
    },
    {
      key: '人口规模',
      name: '人口规模',
      current: Math.round(Number(camp.人口 ?? 0)),
      threshold: '≥20',
      met: camp.人口 >= 20,
      category: '生存与人口',
    },
    {
      key: '防御体系',
      name: '防御类建筑',
      current: defense,
      threshold: '≥2 座',
      met: defense >= 2,
      category: '基础设施',
    },
    {
      key: '仓储体系',
      name: '储存类建筑',
      current: storage,
      threshold: '≥2 座',
      met: storage >= 2,
      category: '基础设施',
    },
    {
      key: '核心火源',
      name: '石砌防风火塘',
      threshold: '已建成',
      met: isBuildingBuilt(data, '石砌防风火塘'),
      category: '基础设施',
    },
    {
      key: '自主生火',
      name: '自主生火工具',
      threshold: '已解锁',
      met: unlocked.includes('火源与热加工') || isBuildingBuilt(data, '钻木取火套装'),
      category: '核心科技',
    },
    {
      key: '制陶技术',
      name: '实用陶器',
      threshold: '已烧制',
      met: hasInventoryMatch(data, /陶/) || hasBuildingMatch(data, /陶/),
      category: '核心科技',
    },
    {
      key: '材料认知跨越',
      name: '材料分级认知',
      threshold: '已解锁',
      met: unlocked.includes('材料分级认知'),
      category: '核心科技',
    },
  ];
}

export function getEraProgressView(data: Schema): {
  title: string;
  categories: EraProgressCategory[];
  progress: Record<string, boolean>;
} {
  const era = data.世界.当前时代;
  const categories = era === '一' ? ERA_ONE_PROGRESS : [];

  return {
    title: ERA_PROGRESS_TITLES[era],
    categories,
    progress: era === '一' ? evaluateEraProgress(data) : {},
  };
}
