import { klona } from 'klona';
import _ from 'lodash';
import { useDataStore } from '../store';
import { readInputText, restoreInputText } from './chatInput';
import { snapshot_ui_state, restore_ui_state } from './useUiStore';
let revision = 0;
const pending = ref(null);
/** 是否存在可取消的待发送操作 */
export const canUndo = computed(() => pending.value !== null);
/** 给界面显示的一行描述 */
export const pendingUndoLabel = computed(() => pending.value?.label ?? '');
function currentChatId() {
    try {
        return globalThis.SillyTavern?.getCurrentChatId?.() ?? '';
    }
    catch {
        return '';
    }
}
/**
 * 在修改 store 之前调用，记录待发送快照。
 * @param inputLine 写进聊天输入框的那段指令文本（无则不参与还原）
 * @param label 展示文案
 */
export function pushUndoSnapshot(inputLine, label = '本次操作') {
    const store = useDataStore();
    const sameChat = pending.value !== null && pending.value.chatId === currentChatId();
    // Claude 的修正：连续操作时只更新标签，**快照保持"第一次脏操作之前"的干净状态**。
    // 否则玩家先派队、再改编队，撤回时会回不到最初的干净态（只能回到第二次操作前）。
    if (sameChat) {
        pending.value.label = label;
        if (inputLine?.trim())
            pending.value.inputLine = inputLine.trim();
        revision += 1;
        console.info('[待发送] 已有待发送事务，快照保持最早状态，仅更新标签');
        return;
    }
    revision += 1;
    pending.value = {
        data: klona(store.data),
        inputLine: inputLine?.trim() || undefined,
        inputBefore: readInputText(),
        uiSnapshot: snapshot_ui_state(),
        label,
        chatId: currentChatId(),
        revision,
        at: Date.now(),
    };
}
function applySnapshot(snapshot) {
    const snap = klona(snapshot);
    const target = useDataStore().data;
    for (const key of _.keys(target)) {
        if (!(key in snap)) {
            delete target[key];
        }
    }
    for (const key of _.keys(snap)) {
        // Schema 增字段后 keyof 联合会让 target[key] 成为交叉类型 → 直写报 TS2322，改走 Record 落值
        target[key] = klona(snap[key]);
    }
}
/**
 * 把整份 stat 直接写回 MVU 真源。
 *
 * 为什么需要显式导出：前端改的是 Pinia 里的 store.data，MVU 那一侧的
 * 消息变量才是真源。普通结算靠 store 的 watch 推写，但**结构性删除**
 * （删掉某个区域 key）如果没落盘，下一次 MVU 拉取就会把它恢复回来
 * —— 实机表现就是「删了过一会儿又变回来」（P-25 的同类问题）。
 */
export async function push_stat_to_mvu(stat) {
    try {
        const MvuGlobal = globalThis.Mvu;
        if (!MvuGlobal?.getMvuData || !MvuGlobal?.replaceMvuData)
            return false;
        const option = { type: 'message', message_id: 'latest' };
        const mvu_data = MvuGlobal.getMvuData(option);
        if (!mvu_data)
            return false;
        mvu_data.stat_data = klona(stat);
        await MvuGlobal.replaceMvuData(mvu_data, option);
        return true;
    }
    catch (error) {
        console.warn('[写回 MVU] 失败', error);
        return false;
    }
}
/** 取消待发送操作：变量与输入框一起还原 */
export async function undoLastAction() {
    const entry = pending.value;
    if (!entry) {
        try {
            toastr.info('没有待发送的操作');
        }
        catch { /* 非酒馆环境 */ }
        return false;
    }
    // 切过档就作废：不同聊天之间回滚变量是灾难
    if (entry.chatId && currentChatId() && entry.chatId !== currentChatId()) {
        pending.value = null;
        try {
            toastr.warning('已切换聊天，无法取消之前的操作');
        }
        catch { /* 非酒馆环境 */ }
        return false;
    }
    applySnapshot(entry.data);
    // 界面状态（hidden_areas 等）不在 stat_data 里，必须单独回滚，否则「忽略区域」取消后区域还是隐藏的
    restore_ui_state(entry.uiSnapshot);
    // 整份还原输入框：玩家可能在指令前后加过自己的话
    restoreInputText(entry.inputBefore ?? '');
    // ★ 必须写回 MVU：只改 store 的话，下一次 pull 会把改回前的值拉回来（实机踩过）
    const target = useDataStore().data;
    await push_stat_to_mvu(target);
    pending.value = null;
    try {
        toastr.info('已取消待发送的操作');
    }
    catch { /* 非酒馆环境 */ }
    return true;
}
/**
 * 玩家真的把指令发出去之后调用：清掉撤回资格（不回滚）。
 * 由抽屉监听 MESSAGE_SENT / GENERATION_STARTED 触发。
 */
export function commitPendingAction() {
    if (pending.value) {
        console.info('[待发送] 指令已发送或已开始生成，撤回资格清除');
    }
    pending.value = null;
}
/** 兼容旧名 */
export function clearUndoStack() {
    pending.value = null;
}
