/**
 * 时代能力表（数据驱动，别写 `if (时代 === '二')`）
 *
 * 每个时代声明：名称、可见模块、退役模块、该时代的主题 class。
 * 前端按这张表渲染面板；加时代/加模块 = 改这张表 + 新增目录，不动入口。
 * 详见 坠星大陆/时代演进与前端架构.md
 */
export type EraId = '一' | '二' | '三'

/** 面板 id 与 panels 注册表里的一致 */
export type PanelId = 'camp' | 'npcs' | 'build' | 'vast' | 'work' | 'era'

export type EraCapability = {
  /** 时代名（面板标题用） */
  名称: string
  /** 这个时代有哪些面板（顺序即标签顺序） */
  面板: PanelId[]
  /** 时代一有、这个时代用不上的（渲染时过滤掉，不删数据） */
  退役面板: PanelId[]
  /** 主题 class（theme.css 里按时代定义 --era-* 变量） */
  主题: string
}

export const ERA_CAPABILITIES: Record<EraId, EraCapability> = {
  一: {
    名称: '火塘时代',
    面板: ['camp', 'npcs', 'build', 'vast', 'work', 'era'],
    退役面板: [],
    主题: 'era-1',
  },
  二: {
    名称: '未命名时代二', // 做时代二时改名
    面板: ['camp', 'npcs', 'build', 'vast', 'work', 'era'],
    退役面板: [],
    主题: 'era-2',
  },
  三: {
    名称: '未命名时代三',
    面板: ['camp', 'npcs', 'build', 'vast', 'work', 'era'],
    退役面板: [],
    主题: 'era-3',
  },
}

/** 把任意输入收成合法时代 id（未知一律落到时代一） */
export function normalize_era(raw: unknown): EraId {
  const s = String(raw ?? '').trim()
  if (/三|III/i.test(s)) return '三'
  if (/二|II/i.test(s)) return '二'
  return '一'
}

export function capability_of(raw_era: unknown): EraCapability {
  return ERA_CAPABILITIES[normalize_era(raw_era)]
}

/** 这个时代可见的面板（已扣掉退役的） */
export function visible_panels(raw_era: unknown): PanelId[] {
  const cap = capability_of(raw_era)
  const retired = new Set(cap.退役面板)
  return cap.面板.filter(id => !retired.has(id))
}
