/**
 * 时代路由：入口只挂这里，不直接挂某个时代的 App。
 *
 * 现在只有时代一（就是原来的 App.vue）。做时代二时：
 *   1. 复制 `界面/状态栏/` 的组件到 `界面/时代二/`（或在同目录新建 EraTwoApp.vue）
 *   2. 在 ERA_APPS 里登记 '二'
 *   3. eraCapabilities 里填面板清单
 * 入口 `index.ts` 不改。
 */
import type { Component } from 'vue'
import type { EraId } from './era/eraCapabilities'
import { normalize_era } from './era/eraCapabilities'
import App from './App.vue'

/** 每个时代对应的根组件；缺哪个就回退到最近可用的一个 */
const ERA_APPS: Partial<Record<EraId, Component>> = {
  一: App,
}

const ERA_ORDER: EraId[] = ['一', '二', '三']

/**
 * 按世界当前时代选根组件。
 * 未实现的时代回退到"不高于它的最近一个有实现的时代"，并在控制台留痕。
 */
export function resolve_era_app(raw_era: unknown): { id: EraId; app: Component } {
  const want = normalize_era(raw_era)
  if (ERA_APPS[want]) {
    return { id: want, app: ERA_APPS[want]! }
  }
  const want_idx = ERA_ORDER.indexOf(want)
  for (let i = want_idx; i >= 0; i -= 1) {
    const id = ERA_ORDER[i]
    const app = ERA_APPS[id]
    if (app) {
      console.warn(`[时代路由] 时代${want} 的界面还没实现，回退到 时代${id}`)
      return { id, app }
    }
  }
  throw new Error('[时代路由] 没有任何时代界面可用')
}

/** 当前已实现的时代（给调试/日志用） */
export function implemented_eras(): EraId[] {
  return ERA_ORDER.filter(id => Boolean(ERA_APPS[id]))
}
