/**
 * 营地编年史（只读，零变量占用）
 *
 * 完整发展历程**不存进变量**——它本来就在聊天记录里。这里扫楼层重建：
 *   1) 正文里的 <settlement_card>（探索/狩猎/采集/交付结算）
 *   2) 当前变量里的【部族日志】（已归档的事务/工作/探索，最多 20 条）
 * 结果只给 UI 看，不进提示词，所以再长也不吃 token。
 */

export type ChronicleEntry = {
  序号: number
  兽历: string
  时间: string
  类型: string
  标题: string
  品质?: string
}

function parse_cards(text: string): Array<{ 类型: string; 标题: string; 品质?: string }> {
  const out: Array<{ 类型: string; 标题: string; 品质?: string }> = []
  const re = /<settlement_card>([\s\S]*?)<\/settlement_card>/g
  let m: RegExpExecArray | null
  while ((m = re.exec(text))) {
    const body = m[1]
    const pick = (key: string) => {
      const r = new RegExp(`\\[${key}\\|([^\\]\\n]+)\\]`)
      const hit = body.match(r)
      return hit ? hit[1].trim() : ''
    }
    const 标题 = pick('标题')
    const 类型 = pick('类型')
    if (!标题 && !类型) continue
    out.push({ 类型: 类型 || '结算', 标题: 标题 || `${类型}结算`, 品质: pick('品质') || undefined })
  }
  return out
}

/** 重建编年史（新的在前） */
export function build_chronicle(limit = 40): ChronicleEntry[] {
  const entries: ChronicleEntry[] = []
  let seq = 0

  // ---- 1) 楼层里的结算卡 ----
  try {
    if (typeof getChatMessages === 'function') {
      const chat = getChatMessages('0-{{lastMessageId}}')
      for (const msg of chat) {
        if (msg.role !== 'assistant') continue
        const st = (msg as unknown as { variables?: Array<{ stat_data?: Record<string, unknown> }> }).variables?.[0]
          ?.stat_data as { 世界?: { 兽历?: string; 时间?: string } } | undefined
        for (const card of parse_cards(String(msg.message ?? ''))) {
          seq += 1
          entries.push({
            序号: seq,
            兽历: st?.世界?.兽历 ?? '',
            时间: st?.世界?.时间 ?? '',
            类型: card.类型,
            标题: card.标题,
            品质: card.品质,
          })
        }
      }
    }
  } catch {
    /* 楼层不可读时只用日志 */
  }

  // ---- 2) 已归档的部族日志 ----
  try {
    const stat = typeof Mvu !== 'undefined'
      ? (Mvu.getMvuData({ type: 'message', message_id: 'latest' })?.stat_data as
          | { 部族日志?: Record<string, Record<string, unknown>> }
          | undefined)
      : null
    for (const log of Object.values(stat?.部族日志 ?? {})) {
      if (!log) continue
      seq += 1
      entries.push({
        序号: seq,
        兽历: String(log.完成日期 ?? ''),
        时间: String(log.完成时日 ?? ''),
        类型: String(log.类型 ?? '日志'),
        标题: String(log.归档摘要 || log.说明 || '归档记录').slice(0, 40),
      })
    }
  } catch {
    /* 忽略 */
  }

  // 去重（同标题同日期只留一条）→ 新的在前
  const seen = new Set<string>()
  const unique = entries.filter(e => {
    const key = `${e.兽历}|${e.标题}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
  return unique.slice(-limit).reverse()
}
