import dedent from 'dedent';
import { capOf } from '../../../balance/timeAdvance';
import { klona } from 'klona';
import {
  CUSTOM_OPTION_ID,
  CUSTOM_START_SECTIONS,
  type CustomStartNotes,
  type CustomStartSelections,
  get_option_label,
} from '../constants/customStartOptions';
import type { Schema } from '../../../schema';
import { useDataStore } from '../store';

const SEASON_LABELS: Record<string, string> = {
  spring: '春季',
  summer: '夏季',
  autumn: '秋季',
  winter: '冬季',
};

function resolve_section_text(
  section_id: string,
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string {
  const section = CUSTOM_START_SECTIONS.find(s => s.id === section_id);
  if (!section) {
    return '';
  }
  const option_id = selections[section_id];
  if (option_id === CUSTOM_OPTION_ID) {
    return custom_notes[section_id]?.trim() || '（玩家未填写）';
  }
  const label = get_option_label(section_id, option_id);
  const option = section.options.find(o => o.id === option_id);
  if (option?.detail && option.id !== CUSTOM_OPTION_ID) {
    return `${label}（${option.detail}）`;
  }
  return label;
}

function stat_hint_for_section(section_id: string, selections: CustomStartSelections): string {
  switch (section_id) {
    case 'region': {
      const id = selections.region;
      if (id === 'forest_edge') return '世界.当前位置=中央大陆林缘';
      if (id === 'frozen_north') return '世界.当前位置=极北冻土边缘';
      if (id === 'sun_scorch') return '世界.当前位置=烈日荒原';
      if (id === 'west_isles') return '世界.当前位置=西部半岛群';
      return '探索主据点随自定义区域写入';
    }
    case 'identity':
      return '主角.威望与称号按玩家填写的身份落地';
    case 'camp':
      return '营地.人口/族人构成/温饱/栖居/向心力按玩家填写落地（未写明时用中立基线）';
    case 'gear':
      return '主角.随身装备按玩家填写的物件落地（未写明则只有破损生存服）'
    case 'season':
      return `世界.季节=${SEASON_LABELS[selections.season] ?? '秋季'}`;
    default:
      return '';
  }
}

export function describe_custom_opening_preset(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string[] {
  return CUSTOM_START_SECTIONS.map(section => {
    const text = resolve_section_text(section.id, selections, custom_notes);
    const hint = stat_hint_for_section(section.id, selections);
    return hint ? `${section.title}：${text}｜${hint}` : `${section.title}：${text}`;
  });
}

