/**
 * 建筑升级规则（时代一）
 *
 * 设计裁决（GLM 与 Gemini-4 分歧后由工程侧定）：
 *  · 等级 1~3 封顶；防御类的「等级」就是「层数」，不再维护两个计数器
 *    （GLM 方案；Gemini 主张层数/等级分离，会重演「忠诚度 vs 好感度」的双计数问题）
 *  · 消耗 = 基础材料 × 1.5（Lv2）/ × 2.5（Lv3），向上取整
 *  · 工时同倍数
 *  · 升级走工作队列，完工才生效（两个模型一致）；升级期间建筑仍算生效，避免防御凭空掉
 */

export const UPGRADE_MAX_LEVEL = 3

/** 目标等级 → 消耗/工时倍数（index = 等级 - 1） */
const FACTOR: Record<number, number> = { 1: 1, 2: 1.5, 3: 2.5 }

export function upgrade_factor(target_level: number): number {
  const lv = Math.min(UPGRADE_MAX_LEVEL, Math.max(1, Math.round(target_level)))
  return FACTOR[lv] ?? 1
}

/** 升级到目标等级所需材料（在基础材料上乘倍数并向上取整） */
export function upgrade_cost(
  base: Record<string, number> | undefined,
  target_level: number,
): Record<string, number> {
  const f = upgrade_factor(target_level)
  const out: Record<string, number> = {}
  for (const [name, amount] of Object.entries(base ?? {})) {
    const n = Math.ceil(Number(amount) * f)
    if (n > 0) out[name] = n
  }
  return out
}

/** 升级工时 */
export function upgrade_hours(base_hours: number | undefined, target_level: number): number {
  const base = Number(base_hours ?? 0)
  if (!Number.isFinite(base) || base <= 0) return 1
  return Math.max(1, Math.ceil(base * upgrade_factor(target_level)))
}

/** 各类型每级的收益文案（供界面显示，纯展示） */
export function upgrade_effect_text(tags: string[] | undefined, level: number): string {
  const lv = Math.min(UPGRADE_MAX_LEVEL, Math.max(1, Math.round(level)))
  const tag = Array.isArray(tags) ? tags : []
  if (tag.includes('防御')) return `每级 +5 防御（当前 Lv${lv} → +${5 * lv}）`
  if (tag.includes('储存')) return `仓库容量 +${25 * lv}%`
  if (tag.includes('医疗')) return `伤病恢复 +${lv}/日`
  if (tag.includes('居住')) return `栖居度与休憩恢复提升（Lv${lv}）`
  if (tag.includes('生产') || tag.includes('制作')) return `产出效率 +${25 * lv}%`
  return `效果随等级提升（Lv${lv}）`
}
